PDL_COMPONENTS.v2PluginDetail=function(p,sc,root){const x=pv(p.data,sc,root);return '<article data-testid="plugin-manager-detail" class="'+V2_RESOURCE_CARD+'"><div class="max-w-[720px] space-y-5 p-4 text-sm [&_label]:text-sm"><header data-plugin-detail-section="identity" class="flex flex-wrap items-center gap-3 border-b border-cafe-border pb-4">'+PDL_COMPONENTS.v2PluginVisual({data:p.data,large:true},sc,root)+'<div class="min-w-0 flex-1"><h3 class="text-sm font-semibold text-cafe">'+h(x.name)+'</h3><p class="mt-1 break-words text-compact text-cafe-muted">'+h(x.version)+' · '+h(x.trust==='unknown'?tc("v2f.copy.w450"):x.trust==='official'?tc("v2f.copy.w461"):x.trust==='first-party'?tc("v2f.copy.w462"):tc("v2f.copy.w463"))+'</p></div>'+(x.installed?'<span class="flex items-center gap-2 text-compact text-cafe-secondary"><span>'+(x.on?tc("v2f.copy.w075"):tc("v2f.copy.w076"))+'</span>'+PDL_COMPONENTS.v2PluginToggle(p,sc,root)+'</span>':'<button type="button" class="console-button-primary !font-medium disabled:opacity-50"'+actAttrs('install',{k:x.key})+(">"+h(tc("v2f.copy.w443"))+"</button>"))+'</header>'+(x.attentionReason?'<section data-plugin-detail-section="attention" class="space-y-3"><div data-inline-notice class="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-x-3 gap-y-2 rounded-lg border border-cafe-border bg-[var(--shell-work)] px-3 py-2.5"><p class="text-sm text-cafe">'+h(v2PluginReason(x))+'</p>'+ (x.canRestart?PDL_COMPONENTS.v2Action({label:tc("v2f.copy.w442"),act:'capRestart',args:{k:x.key}},sc,root):'')+(x.diag?("<details class=\"col-span-2 text-compact text-cafe-muted\"><summary>"+h(tc("v2f.copy.w464"))+"</summary><p class=\"mt-1 break-words text-sm\">")+h(x.diag)+'</p></details>':'')+'<p class="col-span-2 text-sm text-cafe-secondary">'+(x.artifact!=='installed'?tc("v2f.copy.w465"):x.canRestart?tc("v2f.copy.w466"):tc("v2f.copy.w467"))+'</p></div></section>':'')+(x.hasUpdate?("<section data-plugin-detail-section=\"update\" data-inline-notice class=\"flex flex-wrap items-center justify-between gap-3 rounded-lg border border-cafe-border bg-[var(--shell-work)] px-3 py-2.5\"><p class=\"flex items-center gap-2 text-sm text-cafe\"><span class=\"h-2 w-2 rounded-full bg-cafe-accent\"></span>"+h(tc("v2f.copy.w468"))+" ")+h(x.availableVersion)+'</p><button type="button" data-plugin-detail-action="update" class="console-button-secondary !font-medium disabled:opacity-50"'+actAttrs('capUpdate',{k:x.key})+('>'+tc("v2f.copy.w469"))+" "+h(x.availableVersion)+'</button></section>':'')+("<section class=\"space-y-2\" data-plugin-detail-section=\"introduction\"><h4 class=\"text-xs text-cafe-muted font-semibold\">"+h(tc("v2f.copy.w470"))+"</h4><p class=\"text-sm text-cafe-secondary\">")+v2Part({of:'@desc',fmt:'localized'},x,root)+'</p></section>'+pvBlocks(p.body,sc,root)+'<footer data-plugin-detail-section="provenance" class="flex flex-wrap items-center justify-between gap-3 border-t border-cafe-border pt-4"><div class="min-w-0 space-y-1 break-all text-compact text-cafe-muted"><p>'+h(x.repositoryName||x.trust)+'</p><p>'+h(x.pkg)+' · '+h(x.publisher)+" "+tc("v2f.copy.w471")+h(x.availableVersion)+'</p></div>'+(x.canUninstall?'<button type="button" data-plugin-uninstall class="console-button-secondary shrink-0 !font-medium text-conn-red-text disabled:opacity-50"'+actAttrs('remove',{entity:'plugin',id:x.key})+'>'+(x.artifact==='quarantined'?tc("v2f.copy.w472"):tc("v2f.copy.w473"))+'</button>':'')+'</footer></div></article>';};
