PDL_COMPONENTS.v2VoiceSettings=function(p,sc,root){const q=pv(p.data,sc,root),section=function(eyebrow,title,body){return '<section class="console-list-card rounded-xl p-5 shadow-[0_8px_22px_rgba(43,33,26,0.04)]"><div class="space-y-1.5 mb-3"><p class="text-xs font-semibold uppercase tracking-[0.22em] text-cafe-muted">'+eyebrow+'</p><h3 class="text-sm font-semibold text-cafe-secondary">'+title+'</h3></div>'+body+'</section>';},field='text-xs border border-[var(--console-border-soft)] rounded px-2 py-1.5 bg-transparent outline-none transition focus:bg-[var(--console-card-bg)] focus:ring-1 focus:ring-[var(--console-input-stroke)]';return ("<div class=\"space-y-6\"><div class=\"space-y-3 transition-shadow\"><p class=\"text-xs text-cafe-muted font-semibold uppercase tracking-[0.22em]\">"+h(tc("v2f.copy.w474"))+"</p>")+q.svc.map(function(s){return '<div class="'+V2_RESOURCE_CARD+'"><div class="flex items-center gap-4" style="padding:14px 16px"><span class="inline-block h-2 w-2 shrink-0 rounded-full" style="background-color:'+(s.state==='running'?'var(--semantic-success)':s.state==='error'?'var(--semantic-critical)':'var(--shell-muted)')+'"></span><div class="min-w-0 flex-1"><p class="text-sm text-cafe font-medium">'+h(s.name)+'</p><div class="mt-1 min-w-0"><p class="text-xs text-cafe-secondary">'+h(s.impl)+' · '+h({none:tc("v2f.copy.w475"),running:tc("v2f.copy.w476"),stopped:tc("v2f.copy.w477"),installing:tc("v2f.copy.w478"),error:tc("v2f.copy.w366")}[s.state]||s.state)+'</p></div>'+(s.errorText?'<p class="text-xs text-conn-red-text">'+h(s.errorText)+'</p>':'')+(s.log?'<p class="text-xs text-cafe-secondary">'+h(s.log)+'</p>':'')+'</div><div class="flex shrink-0 items-center gap-2">'+(s.canInstall||s.canRetry?PDL_COMPONENTS.v2Action({label:s.canRetry?tc("v2f.copy.w019"):tc("v2f.copy.w443"),act:'svcInstall',args:{i:s.i}},sc,root):s.installed?PDL_COMPONENTS.v2ResourceToggle({value:s.state==='running',act:'setStatus',args:{entity:'svc',id:s.i,v:s.state==='running'?'stopped':'running'}},sc,root):'')+ (s.state==='stopped'?PDL_COMPONENTS.v2ResourceIcon({label:tc("v2f.copy.w479"),icon:'settings',act:'voiceInstallOpen',args:{id:s.i,modify:'1'}},sc,root)+PDL_COMPONENTS.v2ResourceIcon({label:tc("v2f.copy.w480"),icon:'trash',act:'setStatus',args:{entity:'svc',id:s.i,v:'none'}},sc,root):'')+'</div></div></div>';}).join('')+'</div>'+section(tc("v2f.terms.w012"),tc("v2f.copy.w481"),("<p class=\"text-xs text-cafe-secondary mb-2\">"+h(tc("v2f.copy.w482"))+"</p>")+(q.terms.length?'<div class="space-y-1.5 mb-1">'+q.terms.map(function(t){return t.editing?'<div class="ifield flex items-center gap-2 text-xs" data-go="termEditSave" data-for="te-a"><input id="te-a" class="flex-1 '+field+'" value="'+h(t.a)+'"><span>→</span><input id="te-b" class="flex-1 '+field+'" value="'+h(t.b)+'"><button type="button"'+actAttrs('fieldGo',{})+'>✓</button><button type="button"'+actAttrs('close',{path:'ss.termEdit'})+'>×</button></div>':'<div class="flex items-center gap-2 text-xs"><code class="bg-cafe-accent/10 text-cafe-accent px-1.5 py-0.5 rounded">'+h(t.a)+'</code><span class="text-cafe-muted">→</span><code class="bg-conn-green-bg text-conn-green-text px-1.5 py-0.5 rounded">'+h(t.b)+'</code><div class="ml-auto flex items-center gap-1">'+PDL_COMPONENTS.v2ResourceIcon({icon:'file-text',label:tc("v2f.copy.w330"),act:'set',args:{path:'ss.termEdit',v:t.i,cast:'num'}},sc,root)+PDL_COMPONENTS.v2ResourceIcon({icon:'trash',label:tc("v2f.copy.w292"),act:'remove',args:{entity:'voiceTerm',id:t.i}},sc,root)+'</div></div>';}).join('')+'</div>':("<p class=\"text-xs text-cafe-muted italic\">"+h(tc("v2f.copy.w483"))+"</p>"))+'<div class="ifield flex items-center gap-2 mt-2" data-go="add" data-for="term-wrong" data-entity="voiceTerm"><input id="term-wrong" class="flex-1 '+field+("\" placeholder=\""+h(tc("v2f.copy.w484"))+"\"><span class=\"text-cafe-muted text-xs\">→</span><input id=\"term-right\" class=\"flex-1 ")+field+("\" placeholder=\""+h(tc("v2f.copy.w485"))+"\"><button type=\"button\" class=\"text-xs px-2.5 py-1.5 rounded bg-cafe-accent text-[var(--cafe-surface)] hover:bg-cafe-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors\"")+actAttrs('fieldGo',{})+(">"+h(tc("v2f.copy.w117"))+"</button></div>"))+section(tc("v2f.terms.w013"),tc("v2f.copy.w486"),("<details><summary class=\"text-xs text-cafe-interactive hover:text-cafe-accent transition-colors cursor-pointer\">"+h(tc("v2f.copy.w487"))+" ")+q.dictCount+(" "+h(tc("v2f.copy.w488"))+"</summary><div class=\"mt-2 space-y-1 max-h-48 overflow-y-auto\">")+q.dict.map(function(t){return '<div class="flex items-center gap-2 text-xs text-cafe-secondary"><code class="bg-[var(--console-panel-bg)] px-1.5 py-0.5 rounded">'+h(t.a)+'</code><span>→</span><code class="bg-[var(--console-panel-bg)] px-1.5 py-0.5 rounded">'+h(t.b)+'</code></div>';}).join('')+'</div></details>')+section(tc("v2f.terms.w014"),tc("v2f.copy.w489"),("<div class=\"flex items-center gap-3\"><label for=\"stt-lang\" class=\"text-xs text-cafe-secondary\">"+h(tc("v2f.copy.w490"))+"</label><select id=\"stt-lang\" data-change=\"sttLang\" class=\"rounded-lg bg-[var(--console-field-bg)] pl-2 pr-6 py-1.5 text-xs text-cafe-secondary outline-none transition focus:ring-1 focus:ring-[var(--console-input-stroke)]\">")+[['zh',tc("v2f.copy.w491")],['en',tc("v2f.names.English")],['auto',tc("v2f.copy.w492")]].map(function(t){return '<option value="'+t[0]+'"'+(q.sttLang===t[0]?' selected':'')+'>'+t[1]+'</option>';}).join('')+'</select></div>')+section(tc("v2f.terms.w015"),tc("v2f.copy.w493"),("<p class=\"text-xs text-cafe-secondary mb-2\">"+h(tc("v2f.copy.w495"))+"</p><textarea id=\"stt-prompt\" data-input=\"sttPrompt\" rows=\"3\" placeholder=\""+h(tc("v2f.copy.w494"))+"\" class=\"w-full ")+field+' resize-vertical font-mono">'+h(q.prompt)+'</textarea>')+'<div class="flex justify-end"><button type="button" class="text-xs text-cafe-muted hover:text-conn-red-text transition-colors"'+actAttrs('reset',{scope:'voice'})+(">"+h(tc("v2f.copy.w496"))+"</button></div></div>");};
