PDL_COMPONENTS.v2Notifications=function(p,sc,root){const q=pv(p.data,sc,root),push=q.push;if(!push.supported)return ("<div class=\"space-y-3\"><h3 class=\"text-sm font-semibold text-cafe\">"+h(tc("v2f.copy.w497"))+"</h3><div class=\"rounded-2xl border border-conn-amber-ring bg-conn-amber-bg px-5 py-4 space-y-2\"><p class=\"text-sm text-conn-amber-text font-medium\">"+h(tc("v2f.copy.w498"))+"</p><p class=\"text-xs text-conn-amber-text\">"+h(tc("v2f.copy.w499"))+"</p></div></div>");return ("<div class=\"space-y-6\"><section class=\"space-y-3\"><h3 class=\"text-sm font-semibold text-cafe\">"+h(tc("v2f.copy.w497"))+"</h3><div class=\"")+V2_RESOURCE_CARD+' overflow-hidden"><div class="settings-resource-row flex items-center gap-3 px-4 py-3"><span class="flex h-11 w-11 items-center justify-center rounded-xl shrink-0 bg-[var(--cafe-accent,#c96442)]">'+v2HubGlyph('bell','h-5 w-5 text-white')+("</span><div class=\"flex-1 min-w-0\"><p class=\"text-base font-extrabold text-cafe\">"+h(tc("v2f.copy.w500"))+"</p><p class=\"text-xs text-cafe-muted\">")+(push.subscribed?tc("v2f.copy.w501"):push.capability.enabled?tc("v2f.copy.w502"):tc("v2f.copy.w503"))+'</p></div>'+(push.subscribed||push.capability.enabled?PDL_COMPONENTS.v2ResourceToggle({value:push.subscribed,act:'pushToggle',disabled:push.unavailable},sc,root):'')+'</div>'+(push.subscribed?'<div class="flex items-center gap-2 px-5 py-3"><button type="button" class="text-xs text-cafe-secondary hover:text-cafe disabled:opacity-50 transition-colors"'+actAttrs('pushTest',{})+(push.canTest?'':' disabled')+(">"+h(tc("v2f.copy.w504"))+"</button></div>"):'')+(!push.capability.enabled?("<div class=\"px-4 pb-4 pt-3\"><p class=\"mb-3 text-xs text-cafe-muted leading-relaxed\">"+h(tc("v2f.copy.w505"))+" "+"<code class=\"text-micro bg-[var(--console-field-bg)] px-1 py-0.5 rounded\">"+h(tc("v2f.copy.w506"))+"</code>"+" "+h(tc("v2f.copy.w507"))+"</p>")+PDL_COMPONENTS.v2PushServiceConfig({data:{lit:push}},push,root)+'</div>':'')+'</div><div class="'+V2_RESOURCE_CARD+' overflow-hidden"><div class="settings-resource-row flex items-center gap-3 px-4 py-3"><span class="flex h-11 w-11 items-center justify-center rounded-xl shrink-0 bg-conn-emerald-text">'+v2HubGlyph('info','h-5 w-5 text-white')+("</span><div class=\"flex-1 min-w-0\"><p class=\"text-base font-extrabold text-cafe\">"+h(tc("v2f.copy.w508"))+"</p><p class=\"text-xs text-cafe-muted\">"+h(tc("v2f.copy.w509"))+"</p></div><span class=\"shrink-0 rounded-xl px-2.5 py-1 text-xs font-semibold bg-conn-emerald-bg text-conn-emerald-text\">"+h(tc("v2f.copy.w510"))+"</span></div></div></section><section class=\"space-y-3\"><div class=\"flex items-center justify-between\"><h3 class=\"text-sm font-semibold text-cafe\">"+h(tc("v2f.copy.w511"))+"</h3></div><p class=\"text-xs text-cafe-muted\">"+h(tc("v2f.copy.w512"))+"</p><div class=\"")+V2_RESOURCE_CARD+' overflow-hidden divide-y divide-[var(--console-border-soft)]">'+q.notifyTypes.map(function(t){const label={cat:[tc("v2f.copy.w513"),tc("v2f.copy.w514")],perm:[tc("v2f.copy.w515"),tc("v2f.copy.w516")],mention:[tc("v2f.copy.w517"),tc("v2f.copy.w518")],cron:[tc("v2f.copy.w519"),tc("v2f.copy.w520")],signal:[tc("v2f.copy.w521"),tc("v2f.copy.w522")]}[t.id];return '<label class="flex items-center gap-3 px-5 py-3.5 cursor-pointer hover:bg-[var(--console-hover-bg)] transition-colors"><input type="checkbox" class="h-3.5 w-3.5 rounded accent-[var(--color-cafe-accent)]"'+(t.value?' checked':'')+actAttrs('toggle',{path:'s.notify.{k}',k:t.id})+'><span class="text-sm font-medium text-cafe">'+h(label?label[0]:t.id)+'</span><span class="text-xs text-cafe-muted">'+h(label?label[1]:'')+'</span></label>';}).join('')+'</div></section>'+pvBlocks(p.diagnostics,sc,root)+'</div>';};
