PDL_COMPONENTS.v2PreferenceChoices=function(p,sc,root){const q=pvDeep(p,root,sc);return '<section class="space-y-2"><div><h3 class="text-sm font-semibold" style="color:var(--shell-ink)">'+h(q.title)+'</h3>'+(q.note?'<p class="mt-1 text-xs" style="color:var(--shell-muted)">'+h(q.note)+'</p>':'')+'</div><div role="radiogroup" class="flex flex-col gap-1.5">'+q.options.map(function(x){const selected=q.value===x.v;return '<label class="flex items-center gap-3 rounded-lg px-3 py-2 text-left text-sm cursor-pointer" style="background:var(--shell-'+(selected?'selected':'paper')+');border:1px solid var(--shell-hairline);color:var(--shell-ink)"><input type="radio" name="'+h(q.id)+'" value="'+h(x.v)+'"'+(selected?' checked':'')+(q.load==='error'||q.load==='loading'?' disabled':'')+' data-change="'+h(q.change)+'"'+argAttrs(q.args||{})+' class="shell-focusable h-3.5 w-3.5 flex-none accent-[var(--shell-ink)]"><span class="flex-1">'+h(x.label)+(x.note?'<span class="ml-2 text-xs" style="color:var(--shell-muted)">'+h(x.note)+'</span>':'')+'</span></label>';}).join('')+'</div>'+(q.load==='error'?'<output class="mt-1 block text-xs" style="color:var(--shell-muted)">'+h(q.error)+'</output>'+(q.retry?'<button type="button" class="shell-focusable mt-1 text-xs underline"'+actAttrs(q.retry,{})+'>'+h(q.retryLabel)+'</button>':''):'')+'</section>';};
